[CmdletBinding()]param([Parameter(Position=0)][ValidateSet('capture','compare','doctor','help')][string]$Command='capture',[string]$OutputPath=(Join-Path $PWD ('s8-tenant-diff-'+(Get-Date -Format 'yyyyMMdd-HHmmss'))),[string]$BaselinePath,[string]$CurrentPath,[string]$FixturePath,[switch]$InstallDependencies)
Import-Module (Join-Path $PSScriptRoot 'S8.M365.psm1') -Force;Initialize-S8Runtime
if($Command-eq'help'){Write-Output 's8diff capture [-FixturePath fixture.json] | compare -BaselinePath snapshot.json -CurrentPath snapshot.json';exit};if($Command-eq'doctor'){[pscustomobject]@{PowerShell=$PSVersionTable.PSVersion.ToString();Fixture=[bool]$FixturePath}|Format-List;exit}
function Flat($n,$items,$key){@($items|%{[pscustomobject]@{Collection=$n;Key=[string]$_.$key;Fingerprint=($_|ConvertTo-Json -Depth 20 -Compress);Value=$_}})}
New-Item -ItemType Directory $OutputPath -Force|Out-Null
if($Command-eq'compare'){if(-not$BaselinePath-or-not$CurrentPath){throw'compare requires -BaselinePath and -CurrentPath'};$before=@(Get-Content $BaselinePath -Raw|ConvertFrom-Json);$after=@(Get-Content $CurrentPath -Raw|ConvertFrom-Json);$b=@{};$a=@{};foreach($x in $before){$b["$($x.Collection)|$($x.Key)"]=$x};foreach($x in $after){$a["$($x.Collection)|$($x.Key)"]=$x};$diff=@();foreach($k in @($b.Keys+$a.Keys|Sort-Object -Unique)){$status=if(-not$b.ContainsKey($k)){'Added'}elseif(-not$a.ContainsKey($k)){'Removed'}elseif($b[$k].Fingerprint-ne$a[$k].Fingerprint){'Changed'}else{'Unchanged'};if($status-ne'Unchanged'){$parts=$k-split'\|',2;$diff+=[pscustomobject]@{Collection=$parts[0];Key=$parts[1];Change=$status;Before=if($b.ContainsKey($k)){$b[$k].Fingerprint}else{$null};After=if($a.ContainsKey($k)){$a[$k].Fingerprint}else{$null}}}};Export-S8Data $OutputPath 'tenant-diff' $diff;Write-S8Report $OutputPath 'System 8 · M365 Tenant Diff' ([ordered]@{'Changes'=$diff}) 'Offline comparison';[pscustomobject]@{Output=$OutputPath;Changes=$diff.Count};exit}
$ev=New-Object Collections.ArrayList;$ctx=if($FixturePath){[pscustomobject]@{TenantId='fixture';Account='offline'}}else{Connect-S8Graph @('Directory.Read.All','Policy.Read.All','Application.Read.All','Organization.Read.All','Group.Read.All') -InstallDependencies:$InstallDependencies};$spec=[ordered]@{Organization=@('organization','https://graph.microsoft.com/v1.0/organization','id');Domains=@('domains','https://graph.microsoft.com/v1.0/domains','id');ConditionalAccess=@('conditionalAccessPolicies','https://graph.microsoft.com/v1.0/identity/conditionalAccess/policies','id');Applications=@('servicePrincipals','https://graph.microsoft.com/v1.0/servicePrincipals','id');Groups=@('groups','https://graph.microsoft.com/v1.0/groups','id')};$snapshot=@();foreach($n in $spec.Keys){$s=$spec[$n];$data=Invoke-S8SourceCollection $n $s[0] $FixturePath {Get-S8GraphCollection $s[1]} $ev;$snapshot+=Flat $n $data $s[2]};Export-S8Data $OutputPath 'tenant-snapshot' $snapshot;Complete-S8Run $OutputPath 'm365-tenant-diff' capture $ctx $ev $(if($FixturePath){'Offline fixture'}else{'Live Graph'});Write-S8Report $OutputPath 'System 8 · M365 Tenant Snapshot' ([ordered]@{'Snapshot'=$snapshot;'Evidence'=@($ev)});[pscustomobject]@{Output=$OutputPath;Snapshot=(Join-Path $OutputPath 'tenant-snapshot.json');Records=$snapshot.Count}
